import styled from '@emotion/styled';

export const StyledContentCardHeader = styled.div`
  display: flex;
  justify-content: flex-start;
  flex-direction: column;
  gap: 12px;
  background: white;
  padding: 21px 24px;
  border-bottom: 1px solid #14141429;
  margin: -24px -24px 0 -24px;
  border-radius: 16px 16px 0 0;
`;

export const StyledContentCardHeaderTopRow = styled.div`
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 16px;
  width: 100%;
`;

export const StyledTitleTooltipContainer = styled.div`
  display: flex;
  align-items: center;
  gap: 8px;
`;
